style.css:
@-moz-document domain("youtube.com") {
.ytp-time-live-badge:before {
    display: inline-block;
    width: 6px;
    height: 6px;
    margin-right: 5px;
    background: #f03;
    content: '';
    border-radius: 6px;
}

.livestream_chat .header .now {
    left: 57px;
    height: 9px;
    width: 9px;
    background-color: #f03;
    border-radius: 50%;
    top: 20px;
}

.yt-badge-live {
    border: 1px solid #f03;
    color: #f03;
}

.ytp-thumbnail:hover .ytp-large-play-button-svg, .ytp-large-play-button:focus .ytp-large-play-button-svg {
    fill: #f03;
    opacity: 1;
}

.html5-progress-bar:focus .html5-scrubber-button, .html5-scrubber-button:active, .html5-scrubber-button:hover {
    background: #f03;
}

.ytp-volume-slider-foreground:before {
    background: #f03;
    
}
}
